import { test, expect } from '@playwright/test';

test.describe('Background Job Notification via Toast', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/jobs');
  });

  test('should display toast notification when background job completes successfully', async ({ page }) => {
    // Verify job list is visible
    const jobList = page.getByRole('region', { name: /job list/i });
    await expect(jobList).toBeVisible();

    // Click start button for a background job
    const startButton = page.getByRole('button', { name: /start job/i });
    await startButton.click();

    // Verify job is in pending state
    const jobItem = page.getByText(/pending/i);
    await expect(jobItem).toBeVisible();

    // Wait for job to complete (simulate async operation)
    await page.waitForTimeout(1500);

    // Verify job status updates to completed
    const completedJobItem = page.getByText(/completed/i);
    await expect(completedJobItem).toBeVisible();

    // Verify toast notification appears
    const toastNotification = page.getByRole('alert');
    await expect(toastNotification).toBeVisible();
    await expect(toastNotification).toContainText('Job completed successfully');

    // Verify toast has success styling
    const toastContainer = page.locator('[data-testid="toast-container"]');
    await expect(toastContainer).toHaveClass(/toast-success/);
  });

  test('should handle background job failure and display error toast', async ({ page }) => {
    // Click start button for a job that will fail
    const startButton = page.getByRole('button', { name: /start job/i });
    await startButton.click();

    // Verify job is in pending state
    const jobItem = page.getByText(/pending/i);
    await expect(jobItem).toBeVisible();

    // Wait for job to fail (simulate async operation)
    await page.waitForTimeout(1500);

    // Verify job status updates to failed
    const failedJobItem = page.getByText(/failed/i);
    await expect(failedJobItem).toBeVisible();

    // Verify error toast notification appears
    const errorToast = page.getByRole('alert');
    await expect(errorToast).toBeVisible();
    await expect(errorToast).toContainText('Job failed');

    // Verify toast has error styling
    const toastContainer = page.locator('[data-testid="toast-container"]');
    await expect(toastContainer).toHaveClass(/toast-error/);

    // Verify user can retry the failed job
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
    await retryButton.click();

    // Verify job status updates to pending again
    await expect(jobItem).toBeVisible();
  });
});
